document.querySelector('#review-form')?.addEventListener('submit',async e=>{e.preventDefault();let form=e.target,button=form.querySelector('button'),notice=form.querySelector('.form-message')||form.appendChild(Object.assign(document.createElement('p'),{className:'form-message'})),say=(msg,tone='error')=>{notice.className=`form-message ${tone}`;notice.textContent=msg},f=new FormData(form),imageUrl=String(f.get('image_url')||'').trim(),baseReview={name:String(f.get('name')||'').trim(),rating:+f.get('rating'),text:String(f.get('review')||'').trim()},review={...baseReview,approved:false};if(imageUrl)review.image_url=imageUrl;button.disabled=true;button.textContent='Saving review…';say('Saving your review for approval…','saving');try{let save=async payload=>fetch(`${SUPABASE_URL}/rest/v1/reviews`,{method:'POST',headers:{...sbHeaders(),'Content-Type':'application/json',Prefer:'return=minimal'},body:JSON.stringify(payload)}),r=await save(review),raw,error;if(!r.ok&&(imageUrl||'approved'in review)){r=await save(baseReview)}if(!r.ok){raw=await r.text().catch(()=>''),error=null;try{error=raw?JSON.parse(raw):null}catch{}throw new Error(error?.message||error?.details||raw||`Review save failed with status ${r.status}.`)}form.reset();say('Thank you — your review is waiting for SSBS approval.','success')}catch(error){say(error.message||'We could not save your review right now. Please try again.')}finally{button.disabled=false;button.textContent='Share my review'}});
document.querySelector('#offer-form')?.addEventListener('submit',e=>{e.preventDefault();let f=new FormData(e.target),all=offers(),code=String(f.get('code')).trim().toUpperCase();if(all.some(offer=>offer.code===code))return alert('This coupon code already exists.');all.unshift({id:crypto.randomUUID(),title:f.get('title'),code,description:f.get('description'),discount_percent:+f.get('discount_percent'),minimum_order:+f.get('minimum_order')||0,minimum_quantity:+f.get('minimum_quantity')||1,first_order_only:f.get('first_order_only')==='on',banner_text:f.get('banner_text')||null,expires_at:f.get('expires_at')||null,active:true});set('ssbs_offers',all);e.target.reset();renderOffers();renderAdmin();alert('Working coupon published successfully.')});
document.querySelector('#product-form')?.addEventListener('submit',async e=>{e.preventDefault();let form=e.target,f=new FormData(form),all=products(),id=f.get('id'),button=form.querySelector('.button');button.disabled=true;button.textContent='Saving…';try{let uploadedUrl=await uploadProductImage(f.get('image_file')),existing=all.find(product=>product.id===id),item={id:id||crypto.randomUUID(),name:f.get('name'),kind:f.get('kind'),type:f.get('type'),price:+f.get('price'),image_url:uploadedUrl||f.get('image_url')||existing?.image_url||''};let index=all.findIndex(product=>product.id===id);if(index>-1)all[index]=item;else all.unshift(item);set('ssbs_products',all);await adminWrite('products','POST',[item],'?on_conflict=id');await saveProductGallery(item.id,f.getAll('gallery_files'));form.reset();renderProducts();renderAdmin();loadProductGalleries();alert('Product saved successfully.')}catch(error){alert(error.message||'Unable to save product.')}finally{button.disabled=false;button.textContent='Save product'}});
document.querySelector('#upcoming-form')?.addEventListener('submit',async e=>{e.preventDefault();let form=e.target,f=new FormData(form),all=upcomingProducts(),id=f.get('id'),existing=all.find(item=>item.id===id),button=form.querySelector('.button');button.disabled=true;button.textContent='Saving…';try{let uploadedUrl=await uploadProductImage(f.get('image_file')),item={id:id||crypto.randomUUID(),name:String(f.get('name')).trim(),kind:f.get('kind'),description:String(f.get('description')).trim(),launch_date:f.get('launch_date')||null,image_url:uploadedUrl||existing?.image_url||'',active:f.get('active')==='on'},index=all.findIndex(product=>product.id===id);if(index>-1)all[index]=item;else all.unshift(item);localStorage.setItem('ssbs_upcoming_products',JSON.stringify(all));let saved=await adminWrite('upcoming_products','POST',[item],'?on_conflict=id');if(!saved)throw new Error('Upcoming Products table is not ready. Run upcoming-products.sql first.');form.reset();form.elements.active.checked=true;renderUpcoming();alert('Upcoming product saved successfully.')}catch(error){alert(error.message||'Unable to save upcoming product.')}finally{button.disabled=false;button.textContent='Save upcoming product'}});
document.querySelector('#branch-form')?.addEventListener('submit',e=>{e.preventDefault();let f=new FormData(e.target),name=f.get('name'),all=branches();all.push({id:crypto.randomUUID(),name,description:f.get('description')});set('ssbs_branches',all);e.target.reset();renderAdmin()});
document.addEventListener('click',e=>{let id=e.target.dataset.editProduct;if(id){let p=products().find(x=>x.id===id),f=document.querySelector('#product-form');Object.entries(p).forEach(([k,v])=>f.elements[k]&&(f.elements[k].value=v));f.scrollIntoView({behavior:'smooth'})}if(e.target.id==='product-cancel')document.querySelector('#product-form').reset();if(e.target.dataset.deleteProduct){set('ssbs_products',products().filter(p=>p.id!==e.target.dataset.deleteProduct));renderProducts();renderAdmin()}if(e.target.dataset.deleteOffer!==undefined){let a=offers(),item=a[+e.target.dataset.deleteOffer];a.splice(+e.target.dataset.deleteOffer,1);set('ssbs_offers',a);if(document.body.classList.contains('admin')&&item?.id)adminWrite('offers','DELETE',null,`?id=eq.${item.id}`);renderOffers();renderAdmin()}if(e.target.dataset.deleteBranch){set('ssbs_branches',branches().filter(b=>b.id!==e.target.dataset.deleteBranch));renderAdmin()}if(e.target.dataset.toggleReview!==undefined){let a=reviews(),r=a[+e.target.dataset.toggleReview];r.approved=r.approved===false;set('ssbs_reviews',a);renderReviews();renderAdmin()}});
document.addEventListener('click',e=>{if(e.target.dataset.orderPage){orderPage=Number(e.target.dataset.orderPage)||1;renderOrderManager();document.querySelector('.orders-admin .admin-intro')?.scrollIntoView({behavior:'smooth'})}let editId=e.target.dataset.editUpcoming;if(editId){let item=upcomingProducts().find(product=>product.id===editId),form=document.querySelector('#upcoming-form');if(item&&form){Object.entries(item).forEach(([key,value])=>{if(!form.elements[key])return;if(form.elements[key].type==='checkbox')form.elements[key].checked=value!==false;else form.elements[key].value=value??''});form.scrollIntoView({behavior:'smooth'})}}if(e.target.id==='upcoming-cancel'){let form=document.querySelector('#upcoming-form');form.reset();form.elements.active.checked=true}let deleteId=e.target.dataset.deleteUpcoming;if(deleteId&&confirm('Delete this upcoming product?')){let item=upcomingProducts().find(product=>product.id===deleteId);localStorage.setItem('ssbs_upcoming_products',JSON.stringify(upcomingProducts().filter(product=>product.id!==deleteId)));if(item?.id)adminWrite('upcoming_products','DELETE',null,`?id=eq.${item.id}`);renderUpcoming()}});
document.addEventListener('click',e=>{if(!document.body.classList.contains('admin'))return;if(e.target.dataset.deleteProduct)adminWrite('products','DELETE',null,`?id=eq.${e.target.dataset.deleteProduct}`);if(e.target.dataset.deleteBranch)adminWrite('branches','DELETE',null,`?id=eq.${e.target.dataset.deleteBranch}`)},true);
document.addEventListener('click',e=>{let thumb=e.target.closest?.('[data-detail-image]');if(!thumb)return;let main=document.querySelector('#detail-main-image');if(main){main.style.backgroundImage=`url('${thumb.dataset.detailImage}')`;document.querySelectorAll('.detail-thumb').forEach(item=>item.classList.toggle('active',item===thumb))}});
document.addEventListener('change',e=>{let orderNo=e.target.dataset.orderBranch||e.target.dataset.orderStatus||e.target.dataset.orderCourier||e.target.dataset.orderAwb||e.target.dataset.orderTrackingUrl;if(!orderNo)return;let all=orders(),order=all.find(item=>item.id===orderNo);if(!order)return;let update;if(e.target.dataset.orderBranch){order.branch=e.target.value;update={branch_id:e.target.value}}else if(e.target.dataset.orderStatus){order.status=e.target.value;update={status:e.target.value}}else if(e.target.dataset.orderCourier){order.courier=e.target.value;update={courier:e.target.value}}else if(e.target.dataset.orderAwb){order.awb=e.target.value.trim();update={awb:order.awb}}else{order.tracking_url=e.target.value.trim();update={tracking_url:order.tracking_url}}localStorage.setItem('ssbs_orders',JSON.stringify(all));if(document.body.classList.contains('admin'))adminWrite('orders','PATCH',update,`?id=eq.${order.db_id||order.id}`).catch(()=>{});renderOrderManager()});
