function renderProductDetail(){let root=document.querySelector('#product-detail');if(!root)return;let id=new URLSearchParams(location.search).get('id'),p=products().find(x=>x.id===id&&x.active!==false);if(!p){root.innerHTML='<section class="page-head"><h1>Product not found.</h1><a class="button" href="shop.html">Back to shop</a></section>';return}let images=[...new Set([p.image_url,...(p.gallery||[])].filter(Boolean))],hasImage=Boolean(images[0]),visual=hasImage?`style="background-image:url('${images[0]}')" class="detail-image custom-image"`:'class="detail-image"';let concern=p.kind==='hair'?'dryness, frizz and everyday damage':'dullness, dryness and everyday stress';root.innerHTML=`<section class="detail-wrap"><div class="detail-media"><div id="detail-main-image" ${visual}>${hasImage?'':'<div class="product-bottle">SSBS</div>'}</div>${images.length>1?`<div class="detail-thumbs">${images.map((image,index)=>`<button class="detail-thumb ${index===0?'active':''}" data-detail-image="${image}" aria-label="View product photo ${index+1}"><img src="${image}" alt="${p.name} photo ${index+1}"></button>`).join('')}</div>`:''}</div><div class="detail-copy"><p class="eyebrow">${p.type}</p><h1>${p.name}</h1><b class="detail-price">${money(p.price)}</b><p>High-performance professional care, thoughtfully created to address ${concern}. A refined formula for your everyday ritual.</p><div class="detail-notes"><div><b>Why you’ll love it</b><span>Professional-quality care with a sensorial finish.</span></div><div><b>How to use</b><span>Apply as part of your daily self-care ritual. Follow the label directions.</span></div><div><b>Ingredients</b><span>Full ingredient list will be added with the final product information.</span></div></div><button class="button add" data-add="${p.id}">Add to bag</button><a class="text-link" href="shop.html#cart">View your bag →</a></div></section>`}
function initializeApp(){ensureTrustSections();renderProducts();renderUpcoming();renderHomeHero();renderCart();renderOffers();renderReviews();renderAdmin();renderDashboard();renderOrderManager();renderProductDetail();renderCustomerOrders();addConfirmationWhatsapp();startConfirmationRedirect();adminAccessReady.then(allowed=>allowed&&loadLiveStore().catch(()=>null).then(()=>loadProductGalleries().catch(()=>null)));if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').then(registration=>registration.update()).catch(()=>{})}
